namespace local_sentientia_reports\external;

defined('MOODLE_INTERNAL') || die();

/**
 * Security regression tests for delete_report WS — H3 tenant scope.
 *
 * Tests use synthetic tenant IDs (8000+) to avoid collision.
 *
 * @package    local_sentientia_reports
 * @category   test
 */
final class delete_report_test extends \advanced_testcase {

    use \local_sentientia_org\test\bizlms_fixture;

    private function seed_report(?string $open_path, string $name = 'Test report'): int {
        global $DB;
        if (!$DB->get_manager()->table_exists('local_sentientia_reports')) {
            $this->markTestSkipped('local_sentientia_reports table not present.');
        }
        return $DB->insert_record('local_sentientia_reports', (object)[
            'name'         => $name,
            'description'  => 'Generated by phpunit',
            'report_type'  => 'course_completion',
            'filter_config' => null,
            'costcenterid' => 0,
            'open_path'    => $open_path,
            'status'       => 1,
            'created_by'   => 2,
            'runcount'     => 0,
            'timecreated'  => time(),
            'timemodified' => time(),
        ]);
    }

    private function manager_at_path(string $path): \stdClass {
        global $DB;
        $u = $this->getDataGenerator()->create_user();
        $DB->set_field('user', 'open_path', $path, ['id' => $u->id]);
        $u->open_path = $path;
        $sysctx = \context_system::instance();
        $roleid = $this->getDataGenerator()->create_role();
        role_change_permission($roleid, $sysctx, 'local/sentientia_reports:manage', CAP_ALLOW);
        role_assign($roleid, $u->id, $sysctx->id);
        return $u;
    }

    /**
     * H3: caller in /8001 cannot delete a report scoped to /8002.
     */
    public function test_h3_cross_tenant_delete_rejected(): void {
        $this->resetAfterTest();
        $this->ensure_bizlms_schema();

        $other_report = $this->seed_report('/8002', 'Other-tenant report');

        $caller = $this->manager_at_path('/8001');
        $this->setUser($caller);

        $this->expectException(\moodle_exception::class);
        $this->expectExceptionMessage('outoftenant');
        delete_report::execute($other_report);
    }

    /**
     * H3: caller cannot delete a NULL-open_path (site-wide) report —
     * those are siteadmin-only.
     */
    public function test_h3_null_open_path_report_blocked_for_managers(): void {
        $this->resetAfterTest();
        $this->ensure_bizlms_schema();

        $sitewide = $this->seed_report(null, 'Site-wide report');

        $caller = $this->manager_at_path('/8001');
        $this->setUser($caller);

        $this->expectException(\moodle_exception::class);
        $this->expectExceptionMessage('outoftenant');
        delete_report::execute($sitewide);
    }

    /**
     * H3 happy path: caller in /8001 can delete a /8001 report.
     */
    public function test_in_tenant_delete_works(): void {
        global $DB;
        $this->resetAfterTest();
        $this->ensure_bizlms_schema();

        $own_report = $this->seed_report('/8001', 'Own-tenant report');

        $caller = $this->manager_at_path('/8001');
        $this->setUser($caller);

        $r = delete_report::execute($own_report);
        $this->assertTrue($r['success']);
        $this->assertFalse($DB->record_exists('local_sentientia_reports', ['id' => $own_report]));
    }

    /**
     * Caller in /8001/9001 can delete reports under /8001 (parent tenant).
     */
    public function test_descendant_caller_can_delete_parent_tenant_report(): void {
        global $DB;
        $this->resetAfterTest();
        $this->ensure_bizlms_schema();

        $tenant_report = $this->seed_report('/8001', 'Parent-tenant report');

        $caller = $this->manager_at_path('/8001/9001');
        $this->setUser($caller);

        $r = delete_report::execute($tenant_report);
        $this->assertTrue($r['success']);
        $this->assertFalse($DB->record_exists('local_sentientia_reports', ['id' => $tenant_report]));
    }

    /**
     * Siteadmin can delete any report (including NULL open_path).
     */
    public function test_siteadmin_can_delete_any(): void {
        global $DB;
        $this->resetAfterTest();
        $this->ensure_bizlms_schema();
        $this->setAdminUser();

        $r1 = $this->seed_report('/8001');
        $r2 = $this->seed_report('/8002');
        $r3 = $this->seed_report(null);

        $this->assertTrue(delete_report::execute($r1)['success']);
        $this->assertTrue(delete_report::execute($r2)['success']);
        $this->assertTrue(delete_report::execute($r3)['success']);

        $this->assertFalse($DB->record_exists('local_sentientia_reports', ['id' => $r1]));
        $this->assertFalse($DB->record_exists('local_sentientia_reports', ['id' => $r2]));
        $this->assertFalse($DB->record_exists('local_sentientia_reports', ['id' => $r3]));
    }
}
